from datetime import datetime

from .status import Status


class UnexpectedStatus(Status):
    _visibility = None

    def __init__(self, component, name, value):
        """
        :param component: runtime distName of unexpected status component
                          i.e. '/MRBTS-1/RAT-1/RUNTIME_VIEW-1/MRBTS_R-1/EQM_R-1/APEQM_R-1/RMOD_R-1'
        :type component: str
        :param name: name of unexpected status, i.e. 'availabilityStatus'
        :type name: str
        :param value: value of unexpected status, i.e. 'Offline';
                      use None when creating unexpected status without value (i.e. 'Online' after CNI-61110)
        :type value: str or None
        """
        super(UnexpectedStatus, self).__init__(component, name, value)
        self._timestamp = datetime.now()

    @property
    def timestamp(self):
        """
        :return: full date and time from when given status has been created
        :rtype: datetime
        """
        return self._timestamp

    @property
    def visibility(self):
        """
        :return: type of unexpected status visibility, i.e. 'detected'
        :rtype: str
        """
        return self._visibility
